/**
 * @minecraft/server 2.0.0 の最小スタブ（テスト用）。
 *
 * 本物の API のうち、このアドオンが実際に使う部分だけを再現している:
 *   world.beforeEvents / afterEvents の一部, world の動的プロパティ,
 *   system.run / runInterval / runTimeout / clearRun / currentTick,
 *   Dimension.getBlock / spawnItem, Block, BlockPermutation, ItemStack。
 *
 * ここは「ゲームの正しさ」を保証するものではなく、
 * スクリプトが例外を投げずに期待どおりの状態遷移をするかを確かめるためのもの。
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const EquipmentSlot = {
  Mainhand: "Mainhand",
  Offhand: "Offhand",
  Head: "Head",
  Chest: "Chest",
  Legs: "Legs",
  Feet: "Feet",
};

export const GameMode = {
  Survival: "Survival",
  Creative: "Creative",
  Adventure: "Adventure",
  Spectator: "Spectator",
};

export class ItemStack {
  constructor(typeId, amount = 1) {
    this.typeId = typeId;
    this.amount = amount;
    this.nameTag = undefined;
  }
}

// ---- イベントシグナル -------------------------------------------------------

// ---- 読み取り専用コンテキスト -----------------------------------------------
//
// **`world.beforeEvents.*` のハンドラの中では、ワールドを書き換えられない。**
// 書こうとすると本物は
//   "Cannot modify the world in a read-only context" 相当の例外を投げる。
// Bedrock スクリプトの古典的な地雷で、逃げ方は system.run() で次 tick に回すこと。
// スタブがここを再現していないと、**テスト緑のまま実機だけで落ちる**。
//
// afterEvents とブロックのカスタムコンポーネント（onPlayerInteract など）は
// 書き換えてよい。調光ランプの染色が実機で動いているのが根拠。

let readOnlyDepth = 0;

function assertWritable(what) {
  if (readOnlyDepth > 0) {
    throw new Error(
      `${what}: 読み取り専用コンテキスト（beforeEvents）ではワールドを変更できない。` +
        `system.run() で次 tick に回すこと`
    );
  }
}

class Signal {
  /** @param readOnly beforeEvents なら true */
  constructor(readOnly = false) {
    this.handlers = [];
    this.readOnly = readOnly;
  }
  subscribe(fn) {
    this.handlers.push(fn);
    return fn;
  }
  unsubscribe(fn) {
    this.handlers = this.handlers.filter((h) => h !== fn);
  }
  emit(event) {
    if (this.readOnly) readOnlyDepth += 1;
    try {
      for (const h of [...this.handlers]) h(event);
    } finally {
      if (this.readOnly) readOnlyDepth -= 1;
    }
  }
}

// ---- ブロック定義の読み込み（ステートの実在チェック用）----------------------
//
// **本物の `withState()` は、そのブロックが宣言していないステート名を渡すと例外を投げる。**
// スタブが何でも受け付けていると、
//   ・ステート名を打ち間違えた
//   ・ブロック JSON 側の名前を変えたのにスクリプトを直し忘れた
// が **テスト緑のまま実機で「そのブロックだけ動かない」** になる。
// 実際 v1.27.1 で wr:disabled → wr:powered の改名をやっており、
// この手の取りこぼしが起きやすい形になっている。
// そこで実際のブロック JSON を読んで、宣言済みステートだけを許す。

const BLOCK_STATES = new Map(); // typeId -> Set<stateName>
{
  const here = path.dirname(fileURLToPath(import.meta.url));
  const blocksDir = path.join(here, "..", "..", "..", "..", "..", "RedstoneExtBP", "blocks");
  // トレイトで生えるステートは JSON の states には出てこない
  const TRAIT_STATES = {
    "minecraft:placement_direction": ["minecraft:cardinal_direction", "minecraft:facing_direction"],
    "minecraft:placement_position": ["minecraft:block_face", "minecraft:vertical_half"],
  };
  try {
    for (const file of fs.readdirSync(blocksDir)) {
      if (!file.endsWith(".json")) continue;
      const raw = fs.readFileSync(path.join(blocksDir, file), "utf8").replace(/^﻿/, "");
      const desc = JSON.parse(raw)?.["minecraft:block"]?.description;
      if (!desc?.identifier) continue;
      const names = new Set(Object.keys(desc.states ?? {}));
      for (const [trait, cfg] of Object.entries(desc.traits ?? {})) {
        const allowed = TRAIT_STATES[trait] ?? [];
        for (const s of cfg.enabled_states ?? allowed) names.add(s);
      }
      BLOCK_STATES.set(desc.identifier, names);
    }
  } catch {
    // ブロック JSON が読めない環境ではチェックを諦める（スタブ単体で使う場合など）
  }
}

export class BlockPermutation {
  constructor(typeId, states = {}) {
    this.typeId = typeId;
    this.states = { ...states };
    this.type = { id: typeId };
  }
  getState(name) {
    return this.states[name];
  }
  withState(name, value) {
    // 本物と同じく、宣言していないステートは弾く。
    // wr: 以外（テストで置くバニラブロック）は定義を持っていないので素通し。
    const declared = BLOCK_STATES.get(this.typeId);
    if (declared && !declared.has(name)) {
      throw new Error(
        `withState: "${this.typeId}" に "${name}" というステートは無い` +
          `（宣言済み: ${[...declared].join(", ") || "なし"}）`
      );
    }
    return new BlockPermutation(this.typeId, { ...this.states, [name]: value });
  }
  clone() {
    return new BlockPermutation(this.typeId, this.states);
  }
}

class Block {
  constructor(dimension, location, permutation, redstonePower = 0) {
    this.dimension = dimension;
    this.location = { ...location };
    this._permutation = permutation;
    this._redstonePower = redstonePower;
  }
  /**
   * 本物の Bedrock では `block.permutation` は **プロパティではなくネイティブ呼び出し**で、
   * 読むたびに BlockPermutation を作って返す。素のプロパティにしていると
   * プロファイラがこのコストを数えられないので、ここもアクセサにしてある。
   */
  get permutation() {
    return this._permutation;
  }
  set permutation(value) {
    this._permutation = value;
  }
  get typeId() {
    // **`this.permutation` を経由しないこと。** 本物の Bedrock では typeId は
    // permutation とは別のネイティブプロパティなので、経由するとプロファイラが
    // permutation の呼び出し回数を水増ししてしまう（実際に一度誤計測した）。
    return this._permutation.typeId;
  }
  get isAir() {
    return this.typeId === "minecraft:air";
  }
  get isLiquid() {
    return this.typeId === "minecraft:water" || this.typeId === "minecraft:lava";
  }
  getRedstonePower() {
    return this._redstonePower;
  }
  setPermutation(perm) {
    assertWritable("Block.setPermutation");
    this.permutation = perm;
    this.dimension._store(this);
  }
  setType(typeId) {
    assertWritable("Block.setType");
    this.permutation = new BlockPermutation(typeId, {});
    this._redstonePower = 0;
    // 別のブロックになったのでインベントリも消える（チェストを壊した等）
    this.container = undefined;
    this.dimension._store(this);
  }
  offset(delta) {
    return this.dimension.getBlock({
      x: this.location.x + delta.x,
      y: this.location.y + delta.y,
      z: this.location.z + delta.z,
    });
  }
  /**
   * そのブロックをアイテムにしたもの（シルクタッチで採った形）。
   * 本物はアイテム化できないブロック（液体・空気など）で undefined を返す。
   */
  getItemStack(amount = 1) {
    if (this.isAir || this.isLiquid) return undefined;
    return new ItemStack(this.typeId, amount);
  }
  /**
   * テスト用: `block.container = { size, getItem }` を差し込むと
   * インベントリを持つブロック（チェスト等）として振る舞う。
   */
  getComponent(name) {
    if (name === "minecraft:inventory" && this.container) return { container: this.container };
    return undefined;
  }
}

class Dimension {
  constructor(id) {
    this.id = id;
    this.blocks = new Map();
    this.spawnedItems = [];
    /** テスト用: ここに入れた座標は「未ロードチャンク」として undefined を返す。 */
    this.unloaded = new Set();
    /** テスト用: エンティティセンサーが数える対象。{ typeId, location } の配列。 */
    this.entities = [];
  }

  /** テスト用: `dim.weather = "Rain"` と入れると天候センサーが読む。 */
  getWeather() {
    return this.weather;
  }

  /**
   * EntityQueryOptions のうち、このアドオンが実際に使う
   * location / maxDistance / type / excludeTypes だけを再現する。
   */
  getEntities(options = {}) {
    const { location, maxDistance, type, excludeTypes } = options;
    return this.entities.filter((e) => {
      if (type && e.typeId !== type) return false;
      if (excludeTypes && excludeTypes.includes(e.typeId)) return false;
      if (location && maxDistance !== undefined) {
        const dx = e.location.x - location.x;
        const dy = e.location.y - location.y;
        const dz = e.location.z - location.z;
        if (Math.sqrt(dx * dx + dy * dy + dz * dz) > maxDistance) return false;
      }
      return true;
    });
  }
  _key(loc) {
    return `${loc.x},${loc.y},${loc.z}`;
  }
  _store(block) {
    this.blocks.set(this._key(block.location), block);
  }
  getBlock(loc) {
    const key = this._key(loc);
    if (this.unloaded.has(key)) return undefined;
    let block = this.blocks.get(key);
    if (!block) {
      block = new Block(this, loc, new BlockPermutation("minecraft:air", {}));
      this.blocks.set(key, block);
    }
    return block;
  }
  spawnItem(itemStack, location) {
    assertWritable("Dimension.spawnItem");
    this.spawnedItems.push({ itemStack, location });
  }
  /** テスト用: サウンドブロックが鳴らした音を記録する。 */
  playSound(soundId, location, options) {
    if (!this.playedSounds) this.playedSounds = [];
    this.playedSounds.push({ soundId, location, options });
  }
  /** テスト用: スパイクが湧かせる経験値オーブなどを記録する。 */
  spawnEntity(typeId, location) {
    if (!this.spawnedEntities) this.spawnedEntities = [];
    const entity = { typeId, location };
    this.spawnedEntities.push(entity);
    return entity;
  }
  /** テスト用のセットアップヘルパー。 */
  place(loc, typeId, states = {}, redstonePower = 0) {
    const block = new Block(this, loc, new BlockPermutation(typeId, states), redstonePower);
    this._store(block);
    return block;
  }
}

// ---- world ------------------------------------------------------------------

const dimensions = new Map();

const dynamicProperties = new Map();

/** テストドライバが差し込むオンラインプレイヤー。 */
const players = [];

/** テストドライバが setTimeOfDay() で動かすワールド時刻（0〜23999）。 */
let timeOfDay = 6000;

export const world = {
  getAllPlayers() {
    return [...players];
  },
  getTimeOfDay() {
    return timeOfDay;
  },
  setTimeOfDay(value) {
    timeOfDay = value;
  },
  beforeEvents: {
    playerInteractWithBlock: new Signal(true), // 読み取り専用
  },
  afterEvents: {
    playerPlaceBlock: new Signal(),
    playerBreakBlock: new Signal(),
    playerLeave: new Signal(),
    blockExplode: new Signal(),
    worldLoad: new Signal(),
  },
  getDimension(id) {
    if (!dimensions.has(id)) dimensions.set(id, new Dimension(id));
    return dimensions.get(id);
  },
  getDynamicPropertyIds() {
    return [...dynamicProperties.keys()];
  },
  getDynamicProperty(id) {
    return dynamicProperties.get(id);
  },
  /**
   * 本物には **1 件あたりのサイズ上限**がある（文字列で 32,767 バイト）。
   * 超えると例外で、そのプロパティは丸ごと書けない。
   * アクセスログを「1 本の長い文字列」ではなく「1 件 1 プロパティ」に
   * 分けてあるのはこの上限が理由なので、スタブでも再現して設計を裏取りする。
   */
  setDynamicProperty(id, value) {
    assertWritable("world.setDynamicProperty");
    if (value === undefined) {
      dynamicProperties.delete(id);
      return;
    }
    if (typeof value === "string") {
      const bytes = Buffer.byteLength(value, "utf8");
      if (bytes > 32767) {
        throw new Error(
          `setDynamicProperty("${id}"): 文字列が上限 32767 バイトを超えている (${bytes})`
        );
      }
    }
    dynamicProperties.set(id, value);
  },
};

// ---- system -----------------------------------------------------------------

let currentTick = 0;
let nextHandle = 1;
/** handle → { kind, fn, due, interval } */
const jobs = new Map();

export const system = {
  beforeEvents: {
    startup: new Signal(),
  },
  afterEvents: {
    scriptEventReceive: new Signal(),
  },
  get currentTick() {
    return currentTick;
  },
  run(fn) {
    const h = nextHandle++;
    jobs.set(h, { kind: "once", fn, due: currentTick + 1 });
    return h;
  },
  runTimeout(fn, ticks = 1) {
    const h = nextHandle++;
    jobs.set(h, { kind: "once", fn, due: currentTick + Math.max(1, ticks) });
    return h;
  },
  runInterval(fn, ticks = 1) {
    const h = nextHandle++;
    const interval = Math.max(1, ticks);
    jobs.set(h, { kind: "interval", fn, due: currentTick + interval, interval });
    return h;
  },
  clearRun(handle) {
    jobs.delete(handle);
  },
};

// ---- テストドライバ用のエクスポート -----------------------------------------

/** 1 tick 進めて、期限が来たジョブを実行する。 */
export function advanceTick() {
  currentTick += 1;
  for (const [h, job] of [...jobs]) {
    if (job.due > currentTick) continue;
    if (job.kind === "once") jobs.delete(h);
    else job.due = currentTick + job.interval;
    job.fn();
  }
}

export function advanceTicks(n) {
  for (let i = 0; i < n; i += 1) advanceTick();
}

export function addPlayer(player) {
  players.push(player);
  return player;
}

export function removePlayer(id) {
  const i = players.findIndex((p) => p.id === id);
  if (i >= 0) players.splice(i, 1);
}

export function resetWorld() {
  players.length = 0;
  dimensions.clear();
  dynamicProperties.clear();
  jobs.clear();
  currentTick = 0;
  timeOfDay = 6000;
}

export { Block, Dimension };
